import de.rub.nds.tlsattacker.core.layer.impl.QuicFrameLayer;
import de.rub.nds.tlsattacker.core.quic.frame.QuicFrame;
import de.rub.nds.tlsattacker.core.quic.util.VariableLengthIntegerEncoding;
import java.io.ByteArrayInputStream;
import java.util.Arrays;

public class RoundTrip {
    static long readType(ByteArrayInputStream in) throws Exception {
        return VariableLengthIntegerEncoding.readVariableLengthInteger(in);
    }
    static byte[] rt(byte[] wire) throws Exception {
        ByteArrayInputStream in = new ByteArrayInputStream(wire);
        long type = readType(in);
        QuicFrame f = QuicFrameLayer.create(type);
        if (f == null) throw new IllegalStateException("no frame for type " + type);
        f.getParser(in).parse(f);
        if (in.available() != 0) throw new IllegalStateException("unconsumed bytes: " + in.available());
        byte[] out = f.getSerializer().serialize();
        return out;
    }
    static void check(byte[] wire, byte[] expect) throws Exception {
        byte[] out = rt(wire);
        if (!Arrays.equals(out, expect)) {
            System.out.println("FAIL in=" + hex(wire) + " out=" + hex(out) + " expect=" + hex(expect));
        }
    }
    static String hex(byte[] b) { return javax.xml.bind.DatatypeConverter... }
}
EOF
python3 - <<'EOF'
s=open('/tmp/ct/RoundTrip.java').read()
s=s.replace("    static String hex(byte[] b) { return javax.xml.bind.DatatypeConverter... }","""    static String hex(byte[] b) {
        StringBuilder sb = new StringBuilder();
        for (byte x : b) sb.append(String.format("%02x", x));
        return sb.toString();
    }
    public static void main(String[] args) throws Exception {
        // PING, PADDING
        check(new byte[]{0x01}, new byte[]{0x01});
        check(new byte[]{0x00}, new byte[]{0x00});
        // ACK with two extra ranges
        check(new byte[]{0x02, 20, 0, 2, 0, 0, 5, 2, 3}, new byte[]{0x02, 20, 0, 2, 0, 0, 5, 2, 3});
        // ACK_ECN
        check(new byte[]{0x03, 20, 0, 0, 0, 1, 2, 3}, new byte[]{0x03, 20, 0, 0, 0, 1, 2, 3});
        // RESET_STREAM
        check(new byte[]{0x04, 0, 11, 20}, new byte[]{0x04, 0, 11, 20});
        // STOP_SENDING
        check(new byte[]{0x05, 4, 7}, new byte[]{0x05, 4, 7});
        // CRYPTO with overlong offset varint
        check(new byte[]{0x06, 0x40, 0x00, 0x01, (byte) 0xab}, new byte[]{0x06, 0, 1, (byte) 0xab});
        // STREAM OFF|LEN with overlong id
        check(new byte[]{0x0e, 0x40, 0x00, 0x40, 0x01, 2, 'x', 'y'}, new byte[]{0x0e, 0, 1, 2, 'x', 'y'});
        // STREAM FIN only (lengthless)
        check(new byte[]{0x09, 8, 'a', 'b'}, new byte[]{0x09, 8, 'a', 'b'});
        // STREAM no flags
        check(new byte[]{0x08, 8, 'a'}, new byte[]{0x08, 8, 'a'});
        // MAX_DATA
        check(new byte[]{0x10, 0x40, 0x00, 0x05}, new byte[]{0x10, 5});
        // MAX_STREAM_DATA
        check(new byte[]{0x11, 4, 100}, new byte[]{0x11, 4, 100});
        // MAX_STREAMS bidi/uni
        check(new byte[]{0x12, 9}, new byte[]{0x12, 9});
        check(new byte[]{0x13, 9}, new byte[]{0x13, 9});
        // DATA_BLOCKED
        check(new byte[]{0x14, 9}, new byte[]{0x14, 9});
        // STREAM_DATA_BLOCKED
        check(new byte[]{0x15, 4, 9}, new byte[]{0x15, 4, 9});
        // STREAMS_BLOCKED
        check(new byte[]{0x16, 9}, new byte[]{0x16, 9});
        check(new byte[]{0x17, 9}, new byte[]{0x17, 9});
        // NEW_CONNECTION_ID
        byte[] ncid = {0x18, 1, 0, 2, (byte) 0xdd, (byte) 0xee};
        byte[] ncidOut = Arrays.copyOf(ncid, 6 + 16);
        for (int i = 0; i < 16; i++) ncidOut[6 + i] = 0x11;
        check(ncid, ncidOut);
        // RETIRE_CONNECTION_ID
        check(new byte[]{0x19, 3}, new byte[]{0x19, 3});
        // PATH frames
        check(new byte[]{0x1a, 1, 2, 3, 4, 5, 6, 7, 8}, new byte[]{0x1a, 1, 2, 3, 4, 5, 6, 7, 8});
        check(new byte[]{0x1b, 1, 2, 3, 4, 5, 6, 7, 8}, new byte[]{0x1b, 1, 2, 3, 4, 5, 6, 7, 8});
        // CONNECTION_CLOSE (transport) with empty reason
        check(new byte[]{0x1c, 0, 0, 0}, new byte[]{0x1c, 0, 0, 0});
        check(new byte[]{0x1c, 5, 0x40, 0x00, 2, 'o', 'k'}, new byte[]{0x1c, 5, 0, 2, 'o', 'k'});
        // CONNECTION_CLOSE (application)
        check(new byte[]{0x1d, 5, 2, 'o', 'k'}, new byte[]{0x1d, 5, 2, 'o', 'k'});
        // DATAGRAM lengthless and with length
        check(new byte[]{0x30, 'a', 'b'}, new byte[]{0x30, 'a', 'b'});
        check(new byte[]{0x31, 2, 'a', 'b'}, new byte[]{0x31, 2, 'a', 'b'});
        System.out.println("round trip done");
    }""")
